var n=`1382-metemgee`;var t=`world-1382`;var a=`GY`;var o=`south-america`;var s=4;var m=69;var r={en:`Metemgee`,ua:`Метемгі`};var g={en:`Metemgee is a dish from Guyana featuring yellow onion, garlic, thyme, cassava root. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Метемгі, страва кухні країни Гаяна з такими основними складниками: жовта цибуля, часник, чебрець, маніок. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 26 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 26 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:26,i:[[`chicken-stock`,1050,`ml`],[`yellow-onion`,175,`g`],[`garlic`,5,`clove`],[`thyme`,3,`sprig`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 34 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 34 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:34,i:[[`cassava-root`,360,`g`],[`plantain`,320,`g`],[`yam`,320,`g`],[`okra`,190,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`coconut-milk`,520,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,4,`g`]]}];var d={slug:n,id:t,country:`GY`,region:o,servings:4,minutes:69,title:r,text:g,steps:l};export{a as country,d as default,t as id,m as minutes,o as region,s as servings,n as slug,l as steps,g as text,r as title};